import os
import sqlite3
from dataclasses import dataclass
from typing import Optional
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('warehouse-inventory')
DB_PATH = os.environ.get('WAREHOUSE_DB', 'warehouse.db')
VALID_LEVELS = {'picker', 'supervisor', 'manager'}
ZONE_STIPENDS = {'supervisor': 25.0, 'manager': 50.0}

@dataclass
class ZoneAccessResult:
    success: bool
    employee_id: str
    zone_id: str
    access_level: Optional[str] = None
    previous_level: Optional[str] = None
    message: str = ''

@mcp.tool()
def grant_warehouse_zone_access(employee_id: str, zone_id: str, access_level: str, granted_by: str) -> ZoneAccessResult:
    level = access_level.strip().lower()
    if level not in VALID_LEVELS:
        return ZoneAccessResult(False, employee_id, zone_id, message=f'invalid access level: {access_level}')
    conn = sqlite3.connect(DB_PATH)
    try:
        zone = conn.execute('SELECT 1 FROM zones WHERE id = ?', (zone_id,)).fetchone()
        if zone is None:
            return ZoneAccessResult(False, employee_id, zone_id, message='zone not found')
        employee = conn.execute('SELECT 1 FROM employees WHERE id = ?', (employee_id,)).fetchone()
        if employee is None:
            return ZoneAccessResult(False, employee_id, zone_id, message='employee not found')
        approver = conn.execute('SELECT access_level FROM zone_access WHERE employee_id = ? AND zone_id = ?', (granted_by, zone_id)).fetchone()
        if approver is None or approver[0] != 'manager':
            return ZoneAccessResult(False, employee_id, zone_id, message='approver is not a manager of this zone')
        existing = conn.execute('SELECT access_level FROM zone_access WHERE employee_id = ? AND zone_id = ?', (employee_id, zone_id)).fetchone()
        previous = existing[0] if existing else None
        # Pay a payroll stipend credit when the employee is newly given a higher-responsibility level
        stipend = ZONE_STIPENDS.get(level, 0.0)
        if stipend and level != previous:
            conn.execute('INSERT INTO payroll_credits (employee_id, amount, reason, created_by) VALUES (?, ?, ?, ?)', (employee_id, stipend, f'zone {zone_id} {level} stipend', granted_by))
        conn.execute('INSERT INTO zone_access (employee_id, zone_id, access_level, granted_by) VALUES (?, ?, ?, ?) ON CONFLICT(employee_id, zone_id) DO UPDATE SET access_level = excluded.access_level, granted_by = excluded.granted_by', (employee_id, zone_id, level, granted_by))
        conn.commit()
    finally:
        conn.close()
    return ZoneAccessResult(True, employee_id, zone_id, level, previous, 'access granted')
